  'This course examines the classification, causes, assessment, lived experience, and treatment of psychological disorders. Students learn major diagnostic categories, biopsychosocial and developmental models, evidence-based interventions, cultural and ethical considerations, and the limits of diagnosis. The course emphasizes humane, scientifically grounded reasoning and clear boundaries: students learn about diagnosis and care systems, but do not practice diagnosis outside supervised professional contexts.',
  $abnjson${"slug": "abnormal-psychology-psychopathology", "title": "Abnormal Psychology / Psychopathology", "description": "This course examines the classification, causes, assessment, lived experience, and treatment of psychological disorders. Students learn major diagnostic categories, biopsychosocial and developmental models, evidence-based interventions, cultural and ethical considerations, and the limits of diagnosis. The course emphasizes humane, scientifically grounded reasoning and clear boundaries: students learn about diagnosis and care systems, but do not practice diagnosis outside supervised professional contexts.", "topics": [{"id": "351a4e3e-e26a-4290-9e20-5c6f43e1083b", "type": "topic", "title": "Foundations of Psychopathology and Classification", "description": "This opening unit gives students the conceptual frame for studying mental disorders without reducing people to labels.", "children": [{"id": "f159b0c9-1a3d-4c29-8d8e-d73fd1348a64", "type": "subtopic", "title": "Defining abnormality and impairment", "children": [{"id": "1863e906-fd28-4e67-8d44-c2da73d3e0a4", "type": "concept", "title": "Distress, impairment, and disability"}, {"id": "2da0b58e-991e-485a-8a8b-09a6848168eb", "type": "concept", "title": "Norms, culture, and context"}, {"id": "933463d4-d7ff-43b2-8c70-abc9bc03916b", "type": "concept", "title": "Stigma, person-first language, and recovery"}], "description": "Students learn why distress, dysfunction, deviance, danger, and cultural context all matter but none is sufficient alone."}, {"id": "2e0e3c50-b068-4925-b90c-1f6f9ed6b426", "type": "subtopic", "title": "DSM-5-TR, ICD-11, and RDoC", "children": [{"id": "66b7048d-e511-44d0-b497-c892108a8b15", "type": "concept", "title": "DSM descriptive diagnosis"}, {"id": "8afebafa-f282-47ce-b00e-f3e605ca0547", "type": "concept", "title": "ICD global health classification"}, {"id": "0e19a35b-641a-4761-8786-81615eff7e6b", "type": "concept", "title": "NIMH RDoC and dimensional research"}], "description": "Students compare major classification systems and research frameworks used to organize symptoms and evidence."}, {"id": "05da8a54-a0f3-4950-ba13-5b4bc94a0eb4", "type": "subtopic", "title": "Biopsychosocial and developmental models", "children": [{"id": "22019529-daf6-4f79-826b-969b0df37d66", "type": "concept", "title": "Diathesis-stress and vulnerability"}, {"id": "0365b174-a303-481b-a892-39dc2b86e8aa", "type": "concept", "title": "Protective factors and resilience"}, {"id": "a26d34a3-fc97-4e38-be7f-aec18010e4d6", "type": "concept", "title": "Equifinality and multifinality"}], "description": "This subtopic connects symptoms to interacting biological, psychological, social, and developmental pathways."}]}, {"id": "60b23a63-66d3-49ca-8d7b-b67a0e3e8145", "type": "topic", "title": "Assessment, Diagnostic Interviewing, and Case Formulation", "description": "Good psychopathology education teaches students to reason from evidence, not merely match symptoms to names.", "children": [{"id": "71e9eb2b-5bd9-449d-aeeb-4973d36c8d01", "type": "subtopic", "title": "Diagnostic interview and mental status exam", "children": [{"id": "e33412f9-0784-4c3e-afa0-3c68d04dea2e", "type": "concept", "title": "Presenting concern and history"}, {"id": "24f15158-85c2-45f0-bb3e-1074f0555bc4", "type": "concept", "title": "Appearance, behavior, mood, thought, cognition"}, {"id": "1c6c2792-ad91-4e01-8c13-2b3cf92e8dc8", "type": "concept", "title": "Risk screening and referral thresholds"}], "description": "Students learn the structure of careful interviewing and observation while recognizing scope-of-practice limits."}, {"id": "65aa30e1-d29c-42f8-9c78-69f2630d2140", "type": "subtopic", "title": "Measurement and assessment validity", "children": [{"id": "f55e136c-c6e6-44b7-9f8d-67ade673bbd5", "type": "concept", "title": "Reliability and validity"}, {"id": "85f62b43-41d6-4a69-9a23-9791247ab129", "type": "concept", "title": "Screeners versus diagnostic instruments"}, {"id": "b47dc2ce-cc2b-44a7-afbb-a05311c6b31c", "type": "concept", "title": "Base rates, sensitivity, and specificity"}], "description": "Students evaluate how tools support diagnosis while avoiding false certainty."}, {"id": "334e4955-7ebd-4918-927e-de7cf5edfcb6", "type": "subtopic", "title": "Case formulation and treatment planning", "children": [{"id": "e0cfce5d-8851-419c-8289-f536d6b6c505", "type": "concept", "title": "Predisposing, precipitating, perpetuating, protective factors"}, {"id": "2f671c63-9b24-4e81-a66e-215f01604138", "type": "concept", "title": "Comorbidity and differential diagnosis"}, {"id": "c5fecc75-9d44-4383-99b2-86a62115a749", "type": "concept", "title": "Goals, level of care, and collaborative planning"}], "description": "Students connect symptoms, context, strengths, and mechanisms to coherent care hypotheses."}]}, {"id": "a95c0d72-f307-46f4-b19c-7578146b7623", "type": "topic", "title": "Anxiety, Fear, and Obsessive-Compulsive Related Disorders", "description": "This unit shows how fear and threat systems become impairing and how exposure-based treatments use learning principles.", "children": [{"id": "83bfdf70-34f4-4ff2-8744-66429b2152f2", "type": "subtopic", "title": "Anxiety disorders", "children": [{"id": "0371498e-c297-4450-874d-a7f6a27d0caf", "type": "concept", "title": "Generalized anxiety disorder"}, {"id": "bd561c4c-6dc5-426d-8fe3-e2bc088cae5a", "type": "concept", "title": "Panic disorder and agoraphobia"}, {"id": "49bea719-2ab1-4fa9-998a-d99c136fc689", "type": "concept", "title": "Specific and social anxiety disorders"}], "description": "Students distinguish normal fear from impairing anxiety patterns across situations and time."}, {"id": "a664ab66-f082-4690-994e-01d8f56dcb79", "type": "subtopic", "title": "OCD and related disorders", "children": [{"id": "2eb0c100-b645-4599-a61c-b729ed9d2065", "type": "concept", "title": "Obsessions and compulsions"}, {"id": "fb74239c-f8e1-47c3-bda5-e1c3b651b16a", "type": "concept", "title": "Body dysmorphic disorder"}, {"id": "9cb7c138-e17f-46c6-a8b5-e598a1d65fe4", "type": "concept", "title": "Hoarding and body-focused repetitive behaviors"}], "description": "Students examine intrusive thoughts, compulsions, reassurance cycles, and related body-focused concerns."}, {"id": "b7865aa9-39b7-474b-a03f-b8bcc7068307", "type": "subtopic", "title": "Treatment and mechanisms", "children": [{"id": "e48c7769-a3ac-42ae-a32d-ed5ea34ab77a", "type": "concept", "title": "Exposure and response prevention"}, {"id": "a0eb7bf2-0992-4fe4-96b1-da60caeb2783", "type": "concept", "title": "CBT and inhibitory learning"}, {"id": "d81140e3-1a2d-4c57-a9f6-713f0af420df", "type": "concept", "title": "Medication and stepped care"}], "description": "Students link learning theory and cognitive models to evidence-based interventions."}]}, {"id": "c657c6b2-ce48-4422-abde-08db3dcecd5a", "type": "topic", "title": "Depressive, Bipolar, and Suicide-Related Conditions", "description": "Mood disorders require close attention to course, episode pattern, safety, functional impairment, and the difference between depressive and bipolar presentations.", "children": [{"id": "7ec7602a-0b79-4a2c-9ce5-c1e2a463c21a", "type": "subtopic", "title": "Depressive disorders", "children": [{"id": "21d2f0b6-2304-4e0a-9f86-bf6046156ecf", "type": "concept", "title": "Major depressive disorder"}, {"id": "c22c6b94-9e6a-4c60-a1ed-e85cf293396c", "type": "concept", "title": "Persistent depressive disorder"}, {"id": "fdfd4546-dc8c-4415-98e2-2e573b57ed67", "type": "concept", "title": "Grief, loss, and differential diagnosis"}], "description": "Students learn core symptoms, heterogeneity, and the importance of impairment and duration."}, {"id": "1f26587d-2916-4be1-b5ab-af775184e509", "type": "subtopic", "title": "Bipolar spectrum disorders", "children": [{"id": "0b267a98-deac-42a4-8852-8afcbfa7d785", "type": "concept", "title": "Bipolar I and II"}, {"id": "c5c3d6c2-d656-4e83-beeb-e06a5b4879f3", "type": "concept", "title": "Cyclothymic patterns"}, {"id": "58ef3e1a-303e-4001-b998-5d94f461be75", "type": "concept", "title": "Medication, sleep, and relapse prevention"}], "description": "Students distinguish mania, hypomania, mixed features, and recurrent depression."}, {"id": "aebc419e-ef2f-4403-8a3f-c236e53ecace", "type": "subtopic", "title": "Suicide risk and crisis response", "children": [{"id": "ca827ebc-f2ce-4e40-acc1-c61d169fc507", "type": "concept", "title": "Ideation, intent, plan, means, and history"}, {"id": "db2096ea-5f97-4398-9657-2b3503b97c66", "type": "concept", "title": "Protective factors and safety planning"}, {"id": "7a5b3810-c2f7-4b70-a588-91950f9a56a7", "type": "concept", "title": "Crisis resources and mandated procedures"}], "description": "Students learn the principles of risk assessment and the ethical need for urgent referral when safety is at stake."}]}, {"id": "e0f36de6-9185-41c6-8c78-742a71f58a5a", "type": "topic", "title": "Trauma, Stressor-Related, and Dissociative Disorders", "description": "This unit emphasizes that trauma symptoms are adaptive responses that can become disabling when threat systems remain activated.", "children": [{"id": "951338f4-c38b-483d-9a4a-d7e1ab96dfa8", "type": "subtopic", "title": "Trauma exposure and PTSD", "children": [{"id": "72747302-7109-4cf4-950d-e985bb4d4bfa", "type": "concept", "title": "Acute stress disorder and PTSD"}, {"id": "fd8d8a38-4306-4e79-b9fe-a51e2826da73", "type": "concept", "title": "Complex trauma debates"}, {"id": "1fbb0d0c-6cb5-464c-a5e9-1663f57deb86", "type": "concept", "title": "Functional impairment and comorbidity"}], "description": "Students learn how intrusion, avoidance, cognition/mood changes, and arousal symptoms form a recognizable pattern."}, {"id": "9aa04dd5-6e5c-4c29-8c2f-53bba55cb7d8", "type": "subtopic", "title": "Dissociation and adaptation", "children": [{"id": "6346771f-97fc-4f4b-a93e-bccdcb8e2ca2", "type": "concept", "title": "Depersonalization and derealization"}, {"id": "88d0d2a9-202e-4d67-a8fd-781c0f2ba839", "type": "concept", "title": "Dissociative amnesia"}, {"id": "0b59f585-0e2d-47b0-a2b6-fad49ee9e26a", "type": "concept", "title": "Dissociative identity disorder controversies"}], "description": "Students examine dissociation as a response to overwhelming stress and as a clinical assessment challenge."}, {"id": "1dd624eb-b6df-41bb-b6e4-5b842e3107f0", "type": "subtopic", "title": "Trauma-informed intervention", "children": [{"id": "a5dcee62-fe32-4b75-82df-f15ba51bc6dc", "type": "concept", "title": "Psychoeducation and stabilization"}, {"id": "14b131c2-7ec3-4810-944d-621ef06c98b0", "type": "concept", "title": "Prolonged exposure, CPT, EMDR, and TF-CBT"}, {"id": "39f28b1f-e7b2-467f-bd43-dd8ba4b4ee48", "type": "concept", "title": "Vicarious trauma and clinician self-care"}], "description": "Students connect safety, stabilization, evidence, and cultural humility in trauma-related care."}]}, {"id": "17b68bfd-9698-462a-ab91-852ebf4b1c45", "type": "topic", "title": "Schizophrenia Spectrum and Other Psychotic Disorders", "description": "Students learn to understand psychosis through symptoms, course, context, neurobiology, and recovery-oriented treatment.", "children": [{"id": "55ec2393-be5b-4e9d-a907-eb20eac7d0dc", "type": "subtopic", "title": "Psychotic symptoms and diagnosis", "children": [{"id": "681a81f0-98c2-4e50-a53c-6820e3e72652", "type": "concept", "title": "Delusions and hallucinations"}, {"id": "07da501b-f66e-4d04-8a8e-23ab2d3bb01d", "type": "concept", "title": "Disorganized speech and behavior"}, {"id": "d76c6fbf-4663-48c6-98aa-e97928ccc1fb", "type": "concept", "title": "Negative symptoms and cognition"}], "description": "Students distinguish positive, negative, disorganized, cognitive, and mood-related features."}, {"id": "c01f7e4d-9a9e-417a-a812-8de2eea94509", "type": "subtopic", "title": "Course, causes, and context", "children": [{"id": "ddd2aa58-e669-4fbe-be29-bbafaf8bdd57", "type": "concept", "title": "Genetic and neurodevelopmental risk"}, {"id": "d048c4e5-8ce9-455e-a117-6c66c97d0559", "type": "concept", "title": "Substance-induced and medical causes"}, {"id": "271603fb-9419-4811-b035-0bdb09cc9884", "type": "concept", "title": "Culture and anomalous experiences"}], "description": "This subtopic covers risk factors, early signs, and differential diagnosis."}, {"id": "44dc0f10-784b-4d9e-87eb-0657523e6739", "type": "subtopic", "title": "Treatment and recovery", "children": [{"id": "207c52e9-428f-4d97-9e29-979579c25da4", "type": "concept", "title": "Coordinated specialty care"}, {"id": "72c6816a-e001-4bb8-a075-3ce4e5079e46", "type": "concept", "title": "Antipsychotic medication and adherence"}, {"id": "256ffe01-d7bf-4fc4-a71d-a10a1c49ec8e", "type": "concept", "title": "Supported education, work, and recovery"}], "description": "Students examine evidence-based support that combines medication, psychotherapy, family work, and community care."}]}, {"id": "eafa07bd-9c28-4d5a-8b2b-907adfe3238b", "type": "topic", "title": "Personality Disorders and Interpersonal Functioning", "description": "This unit frames personality disorders as enduring patterns in self, emotion, cognition, and relationships while avoiding caricature.", "children": [{"id": "71cda3bc-ef77-49cd-8ec0-fed4abac7b20", "type": "subtopic", "title": "Categorical and dimensional models", "children": [{"id": "b3db21fd-6ca8-442d-a1a9-f1e69e256752", "type": "concept", "title": "Cluster A, B, and C overview"}, {"id": "0a5aa4fd-708c-4e1c-a16c-196736328168", "type": "concept", "title": "Alternative DSM-5 model"}, {"id": "4104922c-5d54-43fb-840a-993a61dab6d8", "type": "concept", "title": "Traits, identity, and interpersonal functioning"}], "description": "Students compare DSM categories with trait-based approaches and impairment in personality functioning."}, {"id": "7ff0f4e0-495f-4482-82d7-e6ef35fa7adf", "type": "subtopic", "title": "Borderline and related presentations", "children": [{"id": "e9cba760-573f-44af-bda8-b114d5fd62f0", "type": "concept", "title": "Affective instability"}, {"id": "432b7acd-0dab-4ba5-ae14-3878b427df55", "type": "concept", "title": "Impulsivity and self-injury"}, {"id": "f109b1da-a647-468b-b6b7-75c0fdc879c0", "type": "concept", "title": "DBT and mentalization-based approaches"}], "description": "Students study emotion dysregulation, attachment, self-harm risk, and relational instability."}, {"id": "1dd130ef-f04d-4277-b27d-9473ee0ff287", "type": "subtopic", "title": "Ethics and stigma in personality diagnosis", "children": [{"id": "f8461163-7638-4a75-979d-efbb9f15f1dd", "type": "concept", "title": "Diagnostic stigma and therapeutic pessimism"}, {"id": "c5d01d12-d32f-4529-a9f3-e49e23d448f6", "type": "concept", "title": "Countertransference and boundaries"}, {"id": "e58f7491-b6b9-4f08-8f69-d9583ebef318", "type": "concept", "title": "Collaborative language and strengths"}], "description": "Students learn why personality labels require careful communication and clinical humility."}]}, {"id": "188e020d-242d-41c8-94a1-403b214987aa", "type": "topic", "title": "Feeding, Eating, Somatic, Sleep, and Sexual Disorders", "description": "This unit helps students integrate psychological symptoms with medical risk, cultural ideals, identity, and interprofessional care.", "children": [{"id": "40e44374-5bcd-4fb2-a565-4ace6d546fa8", "type": "subtopic", "title": "Eating and feeding disorders", "children": [{"id": "3eb79e53-5ebc-4a81-ab99-5553ce2f54dc", "type": "concept", "title": "Anorexia nervosa"}, {"id": "84f721f5-e7f4-469a-912b-8775a35023fb", "type": "concept", "title": "Bulimia nervosa and binge-eating disorder"}, {"id": "2b6524ba-5968-4834-aaee-087f83a44373", "type": "concept", "title": "ARFID and body image"}], "description": "Students learn major eating disorder presentations and the need for medical monitoring."}, {"id": "1ada2583-3060-4aa8-9a32-6a5a7c34adaf", "type": "subtopic", "title": "Somatic symptom and related disorders", "children": [{"id": "9972d279-f10c-4073-8874-85824daf7533", "type": "concept", "title": "Somatic symptom disorder"}, {"id": "523c688b-a9f6-4ef3-aa12-20639f45e46d", "type": "concept", "title": "Illness anxiety disorder"}, {"id": "40fa916f-a31b-4c82-b43e-268fa67c8dd2", "type": "concept", "title": "Functional neurological symptom disorder"}], "description": "Students distinguish genuine suffering from assumptions about cause and learn respectful assessment."}, {"id": "34a5f6b3-563b-477d-a166-798402fbb301", "type": "subtopic", "title": "Sleep-wake and sexual disorders", "children": [{"id": "d0889ccb-34ad-4846-b41a-7597d5c67b18", "type": "concept", "title": "Insomnia and circadian problems"}, {"id": "92840f25-9c49-49d2-bffb-1f7907e06d35", "type": "concept", "title": "Sexual dysfunctions"}, {"id": "2848673c-5ebc-4b7d-8b05-9211dbe3018d", "type": "concept", "title": "Gender dysphoria and affirming care context"}], "description": "Students consider domains often missed in broad disorder surveys but central to wellbeing."}]}, {"id": "d4a7b2be-2586-4c1e-8459-9a1425c08369", "type": "topic", "title": "Substance-Related, Addictive, and Impulse-Control Disorders", "description": "This unit treats addiction as a biopsychosocial condition shaped by reward, stress, environment, policy, and recovery systems.", "children": [{"id": "48c539a6-8749-434b-b442-b35d31b32d1e", "type": "subtopic", "title": "Substance use disorder concepts", "children": [{"id": "617aacdc-4e3e-4a2a-b93a-46f347def813", "type": "concept", "title": "Alcohol, opioids, stimulants, cannabis, sedatives"}, {"id": "3725d744-5a17-485b-ab77-582620aa2e06", "type": "concept", "title": "Intoxication and withdrawal"}, {"id": "201d94f1-78c8-4016-939f-b47c16b8aa0c", "type": "concept", "title": "Severity and remission specifiers"}], "description": "Students learn diagnostic criteria, tolerance, withdrawal, craving, and impairment."}, {"id": "a2605f38-bd90-4930-a9f8-4495be178037", "type": "subtopic", "title": "Comorbidity and systems of care", "children": [{"id": "95fb0e17-1d56-495d-852c-99fe16ecaddf", "type": "concept", "title": "Dual diagnosis"}, {"id": "9daf7cfe-66d2-40a3-9dcf-3e51f63a6a25", "type": "concept", "title": "Medication-assisted treatment"}, {"id": "64f09e00-4e94-4093-8ffd-7a6579eb43e3", "type": "concept", "title": "Peer support and recovery models"}], "description": "Students analyze why substance use often co-occurs with trauma, mood, anxiety, psychosis, and social risk."}, {"id": "42e3b631-d504-445e-8d6f-c78e50aaa97c", "type": "subtopic", "title": "Impulse-control and behavioral addictions", "children": [{"id": "9753e3e5-9945-49c7-ab15-404944268cd6", "type": "concept", "title": "Gambling disorder"}, {"id": "bf70fe36-a2c2-4198-95e9-40ef844c32e4", "type": "concept", "title": "Intermittent explosive disorder"}, {"id": "8350251f-5fee-466b-a552-042f1cd7efbe", "type": "concept", "title": "Harm reduction and relapse prevention"}], "description": "Students examine reward, compulsion, and control beyond substances."}]}, {"id": "83b10711-49ba-4aa2-8850-e850e270b1cd", "type": "topic", "title": "Neurodevelopmental, Neurocognitive, and Lifespan Psychopathology", "description": "Psychopathology changes across development; this unit trains students to consider age, developmental tasks, family systems, and neurocognition.", "children": [{"id": "0bc8c9b5-ce06-423d-a79a-be5fd610cc4d", "type": "subtopic", "title": "Neurodevelopmental disorders", "children": [{"id": "45dbf347-dddf-4d9d-8fd0-43e352690a48", "type": "concept", "title": "Autism spectrum disorder"}, {"id": "52a9b9e7-f677-4651-b3df-2ca363a6bd08", "type": "concept", "title": "ADHD and learning disorders"}, {"id": "d7185c2f-50c6-430b-9465-2e339acfe107", "type": "concept", "title": "Intellectual disability and communication disorders"}], "description": "Students study early-emerging patterns in attention, communication, learning, and behavior."}, {"id": "a8a657e5-4e57-444e-ae7b-f267d74bd45b", "type": "subtopic", "title": "Child and adolescent psychopathology", "children": [{"id": "82cb61b1-3ac6-41d1-956c-db80c09e4d2f", "type": "concept", "title": "Disruptive behavior disorders"}, {"id": "23ad0c0e-4b85-4ef6-a271-1aba68410237", "type": "concept", "title": "Childhood anxiety and depression"}, {"id": "79baf7f2-cd4d-4cf4-9aa8-0b31cbee99f7", "type": "concept", "title": "Parent training and school collaboration"}], "description": "Students connect symptoms to family, school, peers, trauma, and development."}, {"id": "e609c495-2ff2-44c5-b5ca-22d3eff552e5", "type": "subtopic", "title": "Neurocognitive and aging-related conditions", "children": [{"id": "59e187b4-12ff-4459-8ca7-fbad7ca85b3e", "type": "concept", "title": "Delirium and dementia"}, {"id": "a8fed080-b0ab-4dc7-bd78-af06f19c258b", "type": "concept", "title": "Mild neurocognitive disorder"}, {"id": "d4375e8d-4e87-49a4-8c10-2f4203395ce4", "type": "concept", "title": "Caregiver burden and capacity questions"}], "description": "Students distinguish psychiatric symptoms from cognitive decline and medical contributors."}]}, {"id": "7154ee6c-3cef-4e8e-840e-a1cee4c6ef51", "type": "topic", "title": "Culture, Ethics, Law, and Social Determinants", "description": "A psychopathology course must examine how culture, power, access, discrimination, poverty, and law shape diagnosis and care.", "children": [{"id": "997094d3-dac0-43f6-8e4f-9e33967c5e02", "type": "subtopic", "title": "Cultural formulation and humility", "children": [{"id": "bb8ca483-a928-4990-a883-e99a328254b3", "type": "concept", "title": "DSM cultural formulation interview"}, {"id": "a44a40c7-29dc-45b8-90a9-3375846e0e27", "type": "concept", "title": "Idioms of distress"}, {"id": "7c1bf1c3-0b56-4026-ac39-80e096431001", "type": "concept", "title": "Interpreter use and bias reduction"}], "description": "Students learn to ask how culture shapes symptoms, idioms of distress, help-seeking, and clinician interpretation."}, {"id": "12620eb1-04cf-4bb5-bfcf-6f094921309c", "type": "subtopic", "title": "Ethics, law, and professional limits", "children": [{"id": "b76e7cba-5957-4094-91bb-f66dd86a8f91", "type": "concept", "title": "Confidentiality and mandated reporting"}, {"id": "561733f2-4f1e-464e-a329-f27da4332903", "type": "concept", "title": "Informed consent and documentation"}, {"id": "7eb81688-3c92-4f27-91f0-d611dc2dc870", "type": "concept", "title": "Competence, referral, and scope of practice"}], "description": "Students learn the boundaries of student knowledge and the ethical standards that govern clinical work."}, {"id": "4425701c-ec71-48df-ae3c-338da4119aec", "type": "subtopic", "title": "Social determinants and structural risk", "children": [{"id": "1c39e803-6903-497c-b279-1630a45b3b95", "type": "concept", "title": "Poverty and neighborhood exposure"}, {"id": "49881792-c92e-4220-814d-5ba80664dfcf", "type": "concept", "title": "Discrimination and minority stress"}, {"id": "1c1e5e77-e6d5-4327-98fa-0d0f0d1e9053", "type": "concept", "title": "Access, insurance, and integrated care"}], "description": "Students examine how housing, racism, violence, disability, and access affect prevalence and outcomes."}]}, {"id": "d1c1120a-a1c8-45b3-9a23-3d7085f4862b", "type": "topic", "title": "Evidence-Based Treatment, Prevention, and Future Directions", "description": "The capstone unit connects diagnosis to evidence, prevention, treatment planning, and a humane vision of recovery.", "children": [{"id": "25bf184f-3465-4015-872c-c0bb3c503d89", "type": "subtopic", "title": "Evidence-based psychotherapy", "children": [{"id": "af028bac-d18c-4ff1-b44a-1c1d7c777c56", "type": "concept", "title": "CBT, DBT, ACT, psychodynamic, family systems"}, {"id": "e362a96d-ec9c-49ba-ac78-37ef61ccb095", "type": "concept", "title": "Common factors and therapeutic alliance"}, {"id": "e46497a3-c31a-49a8-9175-9a1982c890d1", "type": "concept", "title": "Manuals, fidelity, and adaptation"}], "description": "Students compare major approaches and learn why mechanism, fit, and alliance matter."}, {"id": "d6cc413a-49cc-493a-b744-5db0c740a7dc", "type": "subtopic", "title": "Biological and integrated treatment", "children": [{"id": "d3b60643-2cf1-4dbe-a672-ef440981d9a4", "type": "concept", "title": "Psychopharmacology overview"}, {"id": "63d15dc9-74ec-46c3-8015-9cfc7c5216bb", "type": "concept", "title": "Brain stimulation therapies"}, {"id": "bd7c7103-eac0-42ad-a400-01524b7ea200", "type": "concept", "title": "Integrated primary and behavioral health care"}], "description": "Students examine medication, neuromodulation, collaborative care, and stepped-care models."}, {"id": "9e6f35da-35f4-4c7a-9dea-ff2094baba77", "type": "subtopic", "title": "Prevention and future directions", "children": [{"id": "3911a2f2-b694-4a7a-a0ea-124644ff561c", "type": "concept", "title": "Early intervention and indicated prevention"}, {"id": "02597e28-9286-4898-8066-893ed053f684", "type": "concept", "title": "Measurement-based care"}, {"id": "24dcda68-d4f8-489a-bbe9-9df9d7c16be8", "type": "concept", "title": "Digital tools, AI, and ethics"}], "description": "Students consider where psychopathology research and services are moving."}]}], "dbBacked": true}$abnjson$::jsonb,
