set
  title = 'Abnormal Psychology / Psychopathology',
  goal = 'Abnormal Psychology / Psychopathology',
  summary = 'This course examines the classification, causes, assessment, lived experience, and treatment of psychological disorders. Students learn major diagnostic categories, biopsychosocial and developmental models, evidence-based interventions, cultural and ethical considerations, and the limits of diagnosis. The course emphasizes humane, scientifically grounded reasoning and clear boundaries: students learn about diagnosis and care systems, but do not practice diagnosis outside supervised professional contexts.',
  data = $abnjson${"slug": "abnormal-psychology-psychopathology", "title": "Abnormal Psychology / Psychopathology", "description": "This course examines the classification, causes, assessment, lived experience, and treatment of psychological disorders. Students learn major diagnostic categories, biopsychosocial and developmental models, evidence-based interventions, cultural and ethical considerations, and the limits of diagnosis. The course emphasizes humane, scientifically grounded reasoning and clear boundaries: students learn about diagnosis and care systems, but do not practice diagnosis outside supervised professional contexts.", "topics": [{"id": "351a4e3e-e26a-4290-9e20-5c6f43e1083b", "type": "topic", "title": "Foundations of Psychopathology and Classification", "description": "This opening unit gives students the conceptual frame for studying mental disorders without reducing people to labels.", "children": [{"id": "f159b0c9-1a3d-4c29-8d8e-d73fd1348a64", "type": "subtopic", "title": "Defining abnormality and impairment", "children": [{"id": "1863e906-fd28-4e67-8d44-c2da73d3e0a4", "type": "concept", "title": "Distress, impairment, and disability"}, {"id": "2da0b58e-991e-485a-8a8b-09a6848168eb", "type": "concept", "title": "Norms, culture, and context"}, {"id": "933463d4-d7ff-43b2-8c70-abc9bc03916b", "type": "concept", "title": "Stigma, person-first language, and recovery"}], "description": "Students learn why distress, dysfunction, deviance, danger, and cultural context all matter but none is sufficient alone."}, {"id": "2e0e3c50-b068-4925-b90c-1f6f9ed6b426", "type": "subtopic", "title": "DSM-5-TR, ICD-11, and RDoC", "children": [{"id": "66b7048d-e511-44d0-b497-c892108a8b15", "type": "concept", "title": "DSM descriptive diagnosis"}, {"id": "8afebafa-f282-47ce-b00e-f3e605ca0547", "type": "concept", "title": "ICD global health classification"}, {"id": "0e19a35b-641a-4761-8786-81615eff7e6b", "type": "concept", "title": "NIMH RDoC and dimensional research"}], "description": "Students compare major classification systems and research frameworks used to organize symptoms and evidence."}, {"id": "05da8a54-a0f3-4950-ba13-5b4bc94a0eb4", "type": "subtopic", "title": "Biopsychosocial and developmental models", "children": [{"id": "22019529-daf6-4f79-826b-969b0df37d66", "type": "concept", "title": "Diathesis-stress and vulnerability"}, {"id": "0365b174-a303-481b-a892-39dc2b86e8aa", "type": "concept", "title": "Protective factors and resilience"}, {"id": "a26d34a3-fc97-4e38-be7f-aec18010e4d6", "type": "concept", "title": "Equifinality and multifinality"}], "description": "This subtopic connects symptoms to interacting biological, psychological, social, and developmental pathways."}]}, {"id": "60b23a63-66d3-49ca-8d7b-b67a0e3e8145", "type": "topic", "title": "Assessment, Diagnostic Interviewing, and Case Formulation", "description": "Good psychopathology education teaches students to reason from evidence, not merely match symptoms to names.", "children": [{"id": "71e9eb2b-5bd9-449d-aeeb-4973d36c8d01", "type": "subtopic", "title": "Diagnostic interview and mental status exam", "children": [{"id": "e33412f9-0784-4c3e-afa0-3c68d04dea2e", "type": "concept", "title": "Presenting concern and history"}, {"id": "24f15158-85c2-45f0-bb3e-1074f0555bc4", "type": "concept", "title": "Appearance, behavior, mood, thought, cognition"}, {"id": "1c6c2792-ad91-4e01-8c13-2b3cf92e8dc8", "type": "concept", "title": "Risk screening and referral thresholds"}], "description": "Students learn the structure of careful interviewing and observation while recognizing scope-of-practice limits."}, {"id": "65aa30e1-d29c-42f8-9c78-69f2630d2140", "type": "subtopic", "title": "Measurement and assessment validity", "children": [{"id": "f55e136c-c6e6-44b7-9f8d-67ade673bbd5", "type": "concept", "title": "Reliability and validity"}, {"id": "85f62b43-41d6-4a69-9a23-9791247ab129", "type": "concept", "title": "Screeners versus diagnostic instruments"}, {"id": "b47dc2ce-cc2b-44a7-afbb-a05311c6b31c", "type": "concept", "title": "Base rates, sensitivity, and specificity"}], "description": "Students evaluate how tools support diagnosis while avoiding false certainty."}, {"id": "334e4955-7ebd-4918-927e-de7cf5edfcb6", "type": "subtopic", "title": "Case formulation and treatment planning", "children": [{"id": "e0cfce5d-8851-419c-8289-f536d6b6c505", "type": "concept", "title": "Predisposing, precipitating, perpetuating, protective factors"}, {"id": "2f671c63-9b24-4e81-a66e-215f01604138", "type": "concept", "title": "Comorbidity and differential diagnosis"}, {"id": "c5fecc75-9d44-4383-99b2-86a62115a749", "type": "concept", "title": "Goals, level of care, and collaborative planning"}], "description": "Students connect symptoms, context, strengths, and mechanisms to coherent care hypotheses."}]}, {"id": "a95c0d72-f307-46f4-b19c-7578146b7623", "type": "topic", "title": "Anxiety, Fear, and Obsessive-Compulsive Related Disorders", "description": "This unit shows how fear and threat systems become impairing and how exposure-based treatments use learning principles.", "children": [{"id": "83bfdf70-34f4-4ff2-8744-66429b2152f2", "type": "subtopic", "title": "Anxiety disorders", "children": [{"id": "0371498e-c297-4450-874d-a7f6a27d0caf", "type": "concept", "title": "Generalized anxiety disorder"}, {"id": "bd561c4c-6dc5-426d-8fe3-e2bc088cae5a", "type": "concept", "title": "Panic disorder and agoraphobia"}, {"id": "49bea719-2ab1-4fa9-998a-d99c136fc689", "type": "concept", "title": "Specific and social anxiety disorders"}], "description": "Students distinguish normal fear from impairing anxiety patterns across situations and time."}, {"id": "a664ab66-f082-4690-994e-01d8f56dcb79", "type": "subtopic", "title": "OCD and related disorders", "children": [{"id": "2eb0c100-b645-4599-a61c-b729ed9d2065", "type": "concept", "title": "Obsessions and compulsions"}, {"id": "fb74239c-f8e1-47c3-bda5-e1c3b651b16a", "type": "concept", "title": "Body dysmorphic disorder"}, {"id": "9cb7c138-e17f-46c6-a8b5-e598a1d65fe4", "type": "concept", "title": "Hoarding and body-focused repetitive behaviors"}], "description": "Students examine intrusive thoughts, compulsions, reassurance cycles, and related body-focused concerns."}, {"id": "b7865aa9-39b7-474b-a03f-b8bcc7068307", "type": "subtopic", "title": "Treatment and mechanisms", "children": [{"id": "e48c7769-a3ac-42ae-a32d-ed5ea34ab77a", "type": "concept", "title": "Exposure and response prevention"}, {"id": "a0eb7bf2-0992-4fe4-96b1-da60caeb2783", "type": "concept", "title": "CBT and inhibitory learning"}, {"id": "d81140e3-1a2d-4c57-a9f6-713f0af420df", "type": "concept", "title": "Medication and stepped care"}], "description": "Students link learning theory and cognitive models to evidence-based interventions."}]}, {"id": "c657c6b2-ce48-4422-abde-08db3dcecd5a", "type": "topic", "title": "Depressive, Bipolar, and Suicide-Related Conditions", "description": "Mood disorders require close attention to course, episode pattern, safety, functional impairment, and the difference between depressive and bipolar presentations.", "children": [{"id": "7ec7602a-0b79-4a2c-9ce5-c1e2a463c21a", "type": "subtopic", "title": "Depressive disorders", "children": [{"id": "21d2f0b6-2304-4e0a-9f86-bf6046156ecf", "type": "concept", "title": "Major depressive disorder"}, {"id": "c22c6b94-9e6a-4c60-a1ed-e85cf293396c", "type": "concept", "title": "Persistent depressive disorder"}, {"id": "fdfd4546-dc8c-4415-98e2-2e573b57ed67", "type": "concept", "title": "Grief, loss, and differential diagnosis"}], "description": "Students learn core symptoms, heterogeneity, and the importance of impairment and duration."}, {"id": "1f26587d-2916-4be1-b5ab-af775184e509", "type": "subtopic", "title": "Bipolar spectrum disorders", "children": [{"id": "0b267a98-deac-42a4-8852-8afcbfa7d785", "type": "concept", "title": "Bipolar I and II"}, {"id": "c5c3d6c2-d656-4e83-beeb-e06a5b4879f3", "type": "concept", "title": "Cyclothymic patterns"}, {"id": "58ef3e1a-303e-4001-b998-5d94f461be75", "type": "concept", "title": "Medication, sleep, and relapse prevention"}], "description": "Students distinguish mania, hypomania, mixed features, and recurrent depression."}, {"id": "aebc419e-ef2f-4403-8a3f-c236e53ecace", "type": "subtopic", "title": "Suicide risk and crisis response", "children": [{"id": "ca827ebc-f2ce-4e40-acc1-c61d169fc507", "type": "concept", "title": "Ideation, intent, plan, means, and history"}, {"id": "db2096ea-5f97-4398-9657-2b3503b97c66", "type": "concept", "title": "Protective factors and safety planning"}, {"id": "7a5b3810-c2f7-4b70-a588-91950f9a56a7", "type": "concept", "title": "Crisis resources and mandated procedures"}], "description": "Students learn the principles of risk assessment and the ethical need for urgent referral when safety is at stake."}]}, {"id": "e0f36de6-9185-41c6-8c78-742a71f58a5a", "type": "topic", "title": "Trauma, Stressor-Related, and Dissociative Disorders", "description": "This unit emphasizes that trauma symptoms are adaptive responses that can become disabling when threat systems remain activated.", "children": [{"id": "951338f4-c38b-483d-9a4a-d7e1ab96dfa8", "type": "subtopic", "title": "Trauma exposure and PTSD", "children": [{"id": "72747302-7109-4cf4-950d-e985bb4d4bfa", "type": "concept", "title": "Acute stress disorder and PTSD"}, {"id": "fd8d8a38-4306-4e79-b9fe-a51e2826da73", "type": "concept", "title": "Complex trauma debates"}, {"id": "1fbb0d0c-6cb5-464c-a5e9-1663f57deb86", "type": "concept", "title": "Functional impairment and comorbidity"}], "description": "Students learn how intrusion, avoidance, cognition/mood changes, and arousal symptoms form a recognizable pattern."}, {"id": "9aa04dd5-6e5c-4c29-8c2f-53bba55cb7d8", "type": "subtopic", "title": "Dissociation and adaptation", "children": [{"id": "6346771f-97fc-4f4b-a93e-bccdcb8e2ca2", "type": "concept", "title": "Depersonalization and derealization"}, {"id": "88d0d2a9-202e-4d67-a8fd-781c0f2ba839", "type": "concept", "title": "Dissociative amnesia"}, {"id": "0b59f585-0e2d-47b0-a2b6-fad49ee9e26a", "type": "concept", "title": "Dissociative identity disorder controversies"}], "description": "Students examine dissociation as a response to overwhelming stress and as a clinical assessment challenge."}, {"id": "1dd624eb-b6df-41bb-b6e4-5b842e3107f0", "type": "subtopic", "title": "Trauma-informed intervention", "children": [{"id": "a5dcee62-fe32-4b75-82df-f15ba51bc6dc", "type": "concept", "title": "Psychoeducation and stabilization"}, {"id": "14b131c2-7ec3-4810-944d-621ef06c98b0", "type": "concept", "title": "Prolonged exposure, CPT, EMDR, and TF-CBT"}, {"id": "39f28b1f-e7b2-467f-bd43-dd8ba4b4ee48", "type": "concept", "title": "Vicarious trauma and clinician self-care"}], "description": "Students connect safety, stabilization, evidence, and cultural humility in trauma-related care."}]}, {"id": "17b68bfd-9698-462a-ab91-852ebf4b1c45", "type": "topic", "title": "Schizophrenia Spectrum and Other Psychotic Disorders", "description": "Students learn to understand psychosis through symptoms, course, context, neurobiology, and recovery-oriented treatment.", "children": [{"id": "55ec2393-be5b-4e9d-a907-eb20eac7d0dc", "type": "subtopic", "title": "Psychotic symptoms and diagnosis", "children": [{"id": "681a81f0-98c2-4e50-a53c-6820e3e72652", "type": "concept", "title": "Delusions and hallucinations"}, {"id": "07da501b-f66e-4d04-8a8e-23ab2d3bb01d", "type": "concept", "title": "Disorganized speech and behavior"}, {"id": "d76c6fbf-4663-48c6-98aa-e97928ccc1fb", "type": "concept", "title": "Negative symptoms and cognition"}], "description": "Students distinguish positive, negative, disorganized, cognitive, and mood-related features."}, {"id": "c01f7e4d-9a9e-417a-a812-8de2eea94509", "type": "subtopic", "title": "Course, causes, and context", "children": [{"id": "ddd2aa58-e669-4fbe-be29-bbafaf8bdd57", "type": "concept", "title": "Genetic and neurodevelopmental risk"}, {"id": "d048c4e5-8ce9-455e-a